create table if not exists public.v7_profiles (user_id uuid primary key references auth.users(id) on delete cascade, alias text unique not null, collective_enabled boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.v7_daily_intelligence (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, report_date date not null, report jsonb not null, wisdom jsonb, status text not null default 'completed' check (status in ('processing','completed','failed')), failure_stage text, failure_message text, created_at timestamptz not null default now(), unique(user_id, report_date));
create table if not exists public.v7_collective_wisdom (id uuid primary key default gen_random_uuid(), source_report_id uuid references public.v7_daily_intelligence(id) on delete set null, wisdom jsonb not null, created_at timestamptz not null default now());
create table if not exists public.v7_connection_requests (id uuid primary key default gen_random_uuid(), requester_id uuid not null references auth.users(id) on delete cascade, target_id uuid not null references auth.users(id) on delete cascade, topic text not null, status text not null default 'pending' check (status in ('pending','accepted','declined','cancelled')), created_at timestamptz not null default now(), responded_at timestamptz, unique(requester_id,target_id,topic));
create table if not exists public.v7_mail_threads (id uuid primary key default gen_random_uuid(), created_by uuid not null references auth.users(id) on delete cascade, kind text not null default 'direct' check (kind in ('direct','room','group','list')), subject text, created_at timestamptz not null default now());
create table if not exists public.v7_mail_members (thread_id uuid not null references public.v7_mail_threads(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, joined_at timestamptz not null default now(), primary key(thread_id,user_id));
create table if not exists public.v7_mail_messages (id uuid primary key default gen_random_uuid(), thread_id uuid not null references public.v7_mail_threads(id) on delete cascade, sender_id uuid not null references auth.users(id) on delete cascade, body text, audio_url text, created_at timestamptz not null default now(), constraint message_has_content check (coalesce(length(trim(body)),0)>0 or audio_url is not null));
create index if not exists v7_daily_intelligence_user_date on public.v7_daily_intelligence(user_id,report_date desc);
create index if not exists v7_mail_messages_thread_time on public.v7_mail_messages(thread_id,created_at desc);
create index if not exists v7_connection_target_status on public.v7_connection_requests(target_id,status,created_at desc);
alter table public.v7_profiles enable row level security;
alter table public.v7_daily_intelligence enable row level security;
alter table public.v7_collective_wisdom enable row level security;
alter table public.v7_connection_requests enable row level security;
alter table public.v7_mail_threads enable row level security;
alter table public.v7_mail_members enable row level security;
alter table public.v7_mail_messages enable row level security;
drop policy if exists v7_profiles_own on public.v7_profiles; create policy v7_profiles_own on public.v7_profiles for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists v7_daily_own on public.v7_daily_intelligence; create policy v7_daily_own on public.v7_daily_intelligence for select to authenticated using(user_id=auth.uid());
drop policy if exists v7_daily_insert_own on public.v7_daily_intelligence; create policy v7_daily_insert_own on public.v7_daily_intelligence for insert to authenticated with check(user_id=auth.uid());
drop policy if exists v7_collective_read on public.v7_collective_wisdom; create policy v7_collective_read on public.v7_collective_wisdom for select to authenticated using(true);
drop policy if exists v7_conn_own on public.v7_connection_requests; create policy v7_conn_own on public.v7_connection_requests for select to authenticated using(requester_id=auth.uid() or target_id=auth.uid());
drop policy if exists v7_conn_insert on public.v7_connection_requests; create policy v7_conn_insert on public.v7_connection_requests for insert to authenticated with check(requester_id=auth.uid());
drop policy if exists v7_conn_target_update on public.v7_connection_requests; create policy v7_conn_target_update on public.v7_connection_requests for update to authenticated using(target_id=auth.uid()) with check(target_id=auth.uid());
drop policy if exists v7_thread_member_read on public.v7_mail_threads; create policy v7_thread_member_read on public.v7_mail_threads for select to authenticated using(exists(select 1 from public.v7_mail_members m where m.thread_id=id and m.user_id=auth.uid()));
drop policy if exists v7_thread_create on public.v7_mail_threads; create policy v7_thread_create on public.v7_mail_threads for insert to authenticated with check(created_by=auth.uid());
drop policy if exists v7_member_own on public.v7_mail_members; create policy v7_member_own on public.v7_mail_members for select to authenticated using(user_id=auth.uid());
drop policy if exists v7_member_add on public.v7_mail_members; create policy v7_member_add on public.v7_mail_members for insert to authenticated with check(user_id=auth.uid());
drop policy if exists v7_msg_member_read on public.v7_mail_messages; create policy v7_msg_member_read on public.v7_mail_messages for select to authenticated using(exists(select 1 from public.v7_mail_members m where m.thread_id=thread_id and m.user_id=auth.uid()));
drop policy if exists v7_msg_member_send on public.v7_mail_messages; create policy v7_msg_member_send on public.v7_mail_messages for insert to authenticated with check(sender_id=auth.uid() and exists(select 1 from public.v7_mail_members m where m.thread_id=thread_id and m.user_id=auth.uid()));
create or replace function public.v7_get_or_create_profile() returns public.v7_profiles language plpgsql security definer set search_path=public as $$ declare p public.v7_profiles; a text; begin if auth.uid() is null then raise exception 'AUTHENTICATED_SESSION_REQUIRED'; end if; select * into p from public.v7_profiles where user_id=auth.uid(); if found then return p; end if; a := 'Naya' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,6)); insert into public.v7_profiles(user_id,alias) values(auth.uid(),a) returning * into p; return p; end $$;
revoke all on function public.v7_get_or_create_profile() from public,anon; grant execute on function public.v7_get_or_create_profile() to authenticated;
